-- M6.1 F08: durable event identity. `event_id` is generated by the runtime host
-- and reused on retry; `session_seq` orders events inside one session. Legacy
-- rows keep NULL and are still valid (SQLite UNIQUE allows repeated NULLs).
ALTER TABLE events ADD COLUMN run_id TEXT;
ALTER TABLE events ADD COLUMN event_id TEXT;
ALTER TABLE events ADD COLUMN session_seq INTEGER;
UPDATE events SET run_id = aggregate_id WHERE aggregate_type = 'run' AND run_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_events_run_event_id
  ON events(run_id, event_id) WHERE event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_events_run_session_seq
  ON events(run_id, session_seq) WHERE session_seq IS NOT NULL;

-- M6.1 F06: a review is an assignment (agent or human), bound to the agent that
-- must submit the verdict.
ALTER TABLE reviews ADD COLUMN reviewer_agent_id TEXT;
ALTER TABLE reviews ADD COLUMN assigned_to TEXT NOT NULL DEFAULT 'HUMAN';

-- M6.1 F01: integration evidence is durable before AWAITING_ACCEPTANCE.
CREATE TABLE IF NOT EXISTS integrations (
  id            TEXT PRIMARY KEY,
  task_id       TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  run_id        TEXT NOT NULL,
  commit_sha    TEXT NOT NULL,
  manifest_hash TEXT NOT NULL,
  actor         TEXT,
  at            TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_integrations_task_manifest
  ON integrations(task_id, manifest_hash);

